import{_ as a,o as r,c as t,ax as s}from"./chunks/framework.Bnt0oLax.js";const u=JSON.parse('{"title":"Headers & Query Parameters","description":"Add custom HTTP headers and query parameters to connector requests","frontmatter":{"description":"Add custom HTTP headers and query parameters to connector requests"},"headers":[],"relativePath":"connectors/headers-and-query-parameters.md","filePath":"connectors/headers-and-query-parameters.md"}'),o={name:"connectors/headers-and-query-parameters.md"};function n(i,e,d,l,c,h){return r(),t("div",null,[...e[0]||(e[0]=[s('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/connectors/headers-and-query-parameters.md for this page in Markdown format</div><h1 id="headers-query-parameters" tabindex="-1">Headers &amp; Query Parameters <a class="header-anchor" href="#headers-query-parameters" aria-label="Permalink to &quot;Headers &amp; Query Parameters&quot;">​</a></h1><p>Headers and query parameters let you attach fixed or dynamic values to every connector request. Both support <a href="https://jinja.palletsprojects.com/" target="_blank" rel="noreferrer">Jinja2</a> templates so you can inject user context, secrets, or other runtime values.</p><h2 id="headers" tabindex="-1">Headers <a class="header-anchor" href="#headers" aria-label="Permalink to &quot;Headers&quot;">​</a></h2><p>Add one or more header pairs using <strong>Header Key</strong> and <strong>Header Value</strong>. Use this for things like content type, API versioning, or auth headers.</p><p>Example values:</p><ul><li><strong>Header Key</strong>: <code>Content-Type</code> → <strong>Header Value</strong>: <code>application/json</code></li><li><strong>Header Key</strong>: <code>Accept</code> → <strong>Header Value</strong>: <code>application/vnd.api+json;version=1</code></li></ul><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><p>Add one or more parameter pairs using <strong>Query Key</strong> and <strong>Query Value</strong>. Use this for filters, search terms, pagination, or API keys.</p><p>Example values:</p><ul><li><strong>Query Key</strong>: <code>q</code> → <strong>Query Value</strong>:</li></ul><div class="language-jinja2 vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja2</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">email</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><strong>Query Key</strong>: <code>limit</code> → <strong>Query Value</strong>: <code>50</code></li></ul><h2 id="values-with-spaces-or-special-characters" tabindex="-1">Values with spaces or special characters <a class="header-anchor" href="#values-with-spaces-or-special-characters" aria-label="Permalink to &quot;Values with spaces or special characters&quot;">​</a></h2><p>If you put a value with spaces or special characters directly in the connector <strong>URL</strong>, the connector fails to save. The fix: move that value out of the URL and into a query parameter. The platform encodes query-parameter <strong>values</strong> automatically (spaces and characters like <code>=</code>, <code>&amp;</code>, and quotes), so you never URL-encode them yourself. Auto-encoding applies to query-parameter values, not to the URL field itself.</p><p>For example, to send a search query such as <code>select id from Account where Name = &#39;Acme Corp&#39;</code>:</p><table tabindex="0"><thead><tr><th>Approach</th><th>Result</th></tr></thead><tbody><tr><td>Inline in the URL — <code>https://api.example.com/query?q=select id from Account...</code> <em>(don&#39;t do this)</em></td><td>Rejected — the connector won&#39;t save</td></tr><tr><td><strong>Query Key</strong> <code>q</code> → <strong>Query Value</strong> <code>select id from Account where Name = &#39;Acme Corp&#39;</code></td><td>Works — the value is encoded automatically</td></tr></tbody></table><p>This applies wherever you configure query parameters, including the <code>query_parameters</code> array in <a href="./composite-connectors.html">Build a Composite Connector</a>.</p><h2 id="overridable-fields" tabindex="-1">Overridable fields <a class="header-anchor" href="#overridable-fields" aria-label="Permalink to &quot;Overridable fields&quot;">​</a></h2><p>Each header or query parameter has an <strong>Overridable</strong> checkbox. By default it is off, which means the value is always included in every request and cannot be changed at run time. Turn <strong>Overridable</strong> on when the caller should be able to change the value for a specific request.</p><p>When a field is marked as Overridable and no override is provided at run time, the configured value is used as the default. The field is still sent — it is never omitted just because no override was given.</p><div class="warning custom-block"><p class="custom-block-title">Identity fields should not be overridable</p><p>If a query parameter or header carries user identity (such as a user ID or email), keep <strong>Overridable</strong> off and set the value to a server-side template variable like <code>{{ user.id }}</code>. This ensures the value is injected on the server and cannot be changed by browser code. See <a href="./passing-user-context.html">Passing User Context</a> for details.</p></div><h2 id="when-to-use-path-parameters-instead" tabindex="-1">When to use path parameters instead <a class="header-anchor" href="#when-to-use-path-parameters-instead" aria-label="Permalink to &quot;When to use path parameters instead&quot;">​</a></h2><p>Query parameters live in the URL&#39;s query string (<code>?key=value</code>). For values that go in the URL <strong>path</strong> itself — for example, <code>/users/{id}/posts</code> where <code>{id}</code> varies per call — declare a <strong>path parameter</strong> instead. Each is configured in its own section of the connector; query-parameter entries are appended to the query string, while path-parameter values are substituted into <code>{{ pathParams.X }}</code> template references in the URL path.</p><p>See <a href="./dynamic-url-paths.html">Dynamic URL Path Segments</a> for the full pattern.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./dynamic-url-paths.html">Dynamic URL Path Segments</a> — For values that belong in the URL path, not the query string</li><li><a href="./testing-and-debugging.html">Testing &amp; Debugging</a> — Verify headers and parameters are sent correctly</li><li><a href="./template-variables.html">Template Variables</a> — Jinja2 syntax for dynamic values</li><li><a href="./authentication.html">Authentication</a> — Add auth credentials alongside headers</li></ul>',27)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
